import{_ as e,a,b as i}from"./chunks/setup-smartscreen-2.Bm2h4sAv.js";import{_ as r,a as n}from"./chunks/setup-vrchat-osc.OjexboPL.js";import{_ as l,o,c as s,ag as u}from"./chunks/framework.DTisvaUJ.js";const f=JSON.parse('{"title":"시작하기 — VRChat에서 음성 인식과 읽기 사용","description":"Mutelink 설치부터 VRChat 대화까지 안내합니다. 가상 케이블, VRChat 마이크와 OSC, 빠른 설정을 준비하세요.","frontmatter":{"title":"시작하기 — VRChat에서 음성 인식과 읽기 사용","description":"Mutelink 설치부터 VRChat 대화까지 안내합니다. 가상 케이블, VRChat 마이크와 OSC, 빠른 설정을 준비하세요.","head":[["meta",{"name":"robots","content":"index, follow, max-image-preview:large"}],["link",{"rel":"canonical","href":"https://utyujinn.github.io/Mutelink-releases/ko/guide/getting-started"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"Mutelink"}],["meta",{"property":"og:locale","content":"ko_KR"}],["meta",{"property":"og:title","content":"시작하기 — VRChat에서 음성 인식과 읽기 사용 | Mutelink"}],["meta",{"property":"og:description","content":"Mutelink 설치부터 VRChat 대화까지 안내합니다. 가상 케이블, VRChat 마이크와 OSC, 빠른 설정을 준비하세요."}],["meta",{"property":"og:url","content":"https://utyujinn.github.io/Mutelink-releases/ko/guide/getting-started"}],["meta",{"property":"og:image","content":"https://utyujinn.github.io/Mutelink-releases/images/og-image.png"}],["meta",{"property":"og:image:width","content":"1920"}],["meta",{"property":"og:image:height","content":"1080"}],["meta",{"property":"og:image:alt","content":"Mutelink"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"시작하기 — VRChat에서 음성 인식과 읽기 사용 | Mutelink"}],["meta",{"name":"twitter:description","content":"Mutelink 설치부터 VRChat 대화까지 안내합니다. 가상 케이블, VRChat 마이크와 OSC, 빠른 설정을 준비하세요."}],["meta",{"name":"twitter:image","content":"https://utyujinn.github.io/Mutelink-releases/images/og-image.png"}],["meta",{"name":"twitter:image:alt","content":"Mutelink"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://utyujinn.github.io/Mutelink-releases/guide/getting-started"}],["link",{"rel":"alternate","hreflang":"en","href":"https://utyujinn.github.io/Mutelink-releases/en/guide/getting-started"}],["link",{"rel":"alternate","hreflang":"zh-Hans","href":"https://utyujinn.github.io/Mutelink-releases/zh/guide/getting-started"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://utyujinn.github.io/Mutelink-releases/ko/guide/getting-started"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://utyujinn.github.io/Mutelink-releases/guide/getting-started"}]]},"headers":[],"relativePath":"ko/guide/getting-started.md","filePath":"ko/guide/getting-started.md"}'),h={name:"ko/guide/getting-started.md"};function p(g,t,d,m,c,k){return o(),s("div",null,[...t[0]||(t[0]=[u('<h1 id="はじめかた" tabindex="-1">시작하기 <a class="header-anchor" href="#はじめかた" aria-label="Permalink to &quot;시작하기 {#はじめかた}&quot;">​</a></h1><p>설치부터 VRChat에서 대화하기까지의 과정입니다. 앱 내부는 첫 실행 시 빠른 설정이 안내하며, 여기서는 앱 외부의 준비를 설명합니다.</p><h2 id="_1-vb-audio-virtual-cableを入れる" tabindex="-1">1. VB-Audio Virtual Cable 설치 <a class="header-anchor" href="#_1-vb-audio-virtual-cableを入れる" aria-label="Permalink to &quot;1. VB-Audio Virtual Cable 설치 {#_1-vb-audio-virtual-cableを入れる}&quot;">​</a></h2><p>합성 음성을 VRChat 마이크로 보내는 무료 소프트웨어입니다. 채팅창만 사용한다면 건너뛰세요.</p><ol><li><a href="https://vb-audio.com/Cable/" target="_blank" rel="noreferrer">VB-Audio Virtual Cable</a>을 다운로드하고 설치합니다.</li><li>Windows 소리 설정에 “CABLE Input”과 “CABLE Output”이 있는지 확인합니다. 없다면 PC를 다시 시작하세요.</li></ol><p><strong>Mutelink보다 먼저 설치하세요.</strong> Mutelink가 열린 상태에서 설치했다면 앱을 다시 시작하세요.</p><p><img src="'+e+'" alt="Windows 소리 설정의 CABLE Input과 CABLE Output"></p><h2 id="_2-mutelinkをインストールする" tabindex="-1">2. Mutelink 설치 <a class="header-anchor" href="#_2-mutelinkをインストールする" aria-label="Permalink to &quot;2. Mutelink 설치 {#_2-mutelinkをインストールする}&quot;">​</a></h2><ol><li><a href="https://github.com/utyujinn/Mutelink-releases/releases" target="_blank" rel="noreferrer">Releases</a> 또는 <a href="https://utyujin.booth.pm/items/8914909" target="_blank" rel="noreferrer">BOOTH</a>에서 설치 파일(<code>Mutelink_x.x.x_x64-setup.exe</code>)을 받습니다.</li><li>실행합니다. 관리자 권한은 필요하지 않습니다.</li></ol><p>코드 서명이 없어 “Windows의 PC 보호”가 표시될 수 있습니다. “추가 정보”를 누른 다음 “실행”을 누르세요.</p><table tabindex="0"><thead><tr><th>① “추가 정보” 클릭</th><th>② “실행” 클릭</th></tr></thead><tbody><tr><td><img src="'+a+'" alt="추가 정보 클릭"></td><td><img src="'+i+'" alt="실행 클릭"></td></tr></tbody></table><h2 id="_3-クイックセットアップを進める" tabindex="-1">3. 빠른 설정 진행 <a class="header-anchor" href="#_3-クイックセットアップを進める" aria-label="Permalink to &quot;3. 빠른 설정 진행 {#_3-クイックセットアップを進める}&quot;">​</a></h2><p>첫 실행 시 빠른 설정이 열립니다. 음성 대화, 번역, 키보드 입력, 상대 음성 자막, VR 등 용도를 선택하면 필요한 설정만 차례로 표시됩니다.</p><p>다음 세 가지를 특히 확인하세요.</p><ul><li><strong>마이크</strong>: 실제로 말할 마이크를 선택하세요. 합성 음성을 다시 인식하므로 “CABLE Output”은 선택하지 마세요.</li><li><strong>스피커</strong>: 읽기 기능을 쓸 때는 VRChat으로 보낼 “CABLE Input”과 직접 들을 스피커 또는 헤드폰을 모두 선택하세요.</li><li><strong>음성 인식과 읽기 목소리</strong>: <a href="/Mutelink-releases/ko/compare/speech-recognition">음성 인식 엔진 비교</a>와 <a href="/Mutelink-releases/ko/compare/voices">목소리 비교</a>를 참고하세요. 나중에도 바꿀 수 있습니다.</li></ul><p>설정 &gt; 사용 방식에서 빠른 설정을 다시 실행할 수 있습니다.</p><h2 id="_4-vrchat側を設定する" tabindex="-1">4. VRChat 설정 <a class="header-anchor" href="#_4-vrchat側を設定する" aria-label="Permalink to &quot;4. VRChat 설정 {#_4-vrchat側を設定する}&quot;">​</a></h2><h3 id="声を流すとき" tabindex="-1">목소리를 보낼 때 <a class="header-anchor" href="#声を流すとき" aria-label="Permalink to &quot;목소리를 보낼 때 {#声を流すとき}&quot;">​</a></h3><p>VRChat 설정 &gt; 오디오에서 마이크를 “CABLE Output”으로 선택하세요.</p><div class="warning custom-block"><p class="custom-block-title">“기본값(Default)”으로 두지 마세요</p><p>“기본값”이면 실제 마이크가 선택되어 자신의 목소리가 VRChat으로 전달될 수 있습니다. 반드시 “CABLE Output”을 선택하세요.</p></div><p>읽기 음성이 잘리지 않도록 VRChat 마이크를 토글로 켜 둔 상태로 사용하는 것을 권장합니다.</p><p><img src="'+r+'" alt="VRChat 마이크를 CABLE Output으로 설정"></p><h3 id="チャットボックスだけで使うとき" tabindex="-1">채팅창만 사용할 때 <a class="header-anchor" href="#チャットボックスだけで使うとき" aria-label="Permalink to &quot;채팅창만 사용할 때 {#チャットボックスだけで使うとき}&quot;">​</a></h3><p>VRChat 마이크를 음소거하세요. 그렇지 않으면 음성 인식을 위해 말한 목소리가 그대로 상대에게 들립니다.</p><h3 id="チャットボックスを使うとき" tabindex="-1">채팅창을 사용할 때 <a class="header-anchor" href="#チャットボックスを使うとき" aria-label="Permalink to &quot;채팅창을 사용할 때 {#チャットボックスを使うとき}&quot;">​</a></h3><p>VRChat에서 OSC를 켭니다(원형 메뉴 &gt; Options &gt; OSC &gt; Enabled).</p><p><img src="'+n+'" alt="VRChat OSC 활성화"></p><h2 id="_5-使ってみる" tabindex="-1">5. 사용해 보기 <a class="header-anchor" href="#_5-使ってみる" aria-label="Permalink to &quot;5. 사용해 보기 {#_5-使ってみる}&quot;">​</a></h2><p>메인 화면에서 음성 인식을 켜고 마이크에 말하세요. 인식된 글을 확인하고 전송하거나 자동 전송을 켤 수 있습니다.</p><p>설정 오른쪽 위의 “?”를 누르면 버튼과 설정의 설명이 표시됩니다.</p><p>문제가 있다면 <a href="/Mutelink-releases/ko/help/troubleshooting">문제 해결</a>을 참고하세요.</p>',31)])])}const V=l(h,[["render",p]]);export{f as __pageData,V as default};
